<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createReceivingOrder, getReceivingOrders, completeReceivingOrder, exportReceivingItems } from '../../api/receivingOrder'
import { getSuppliers } from '../../api/supplier'
import type { ReceivingOrder, Supplier } from '../../api/types'
const router=useRouter(); const loading=ref(false); const dialogVisible=ref(false); const suppliers=ref<Supplier[]>([]); const rows=ref<ReceivingOrder[]>([]); const total=ref(0)
const query=reactive({pageNum:0,pageSize:10,supplierId:undefined as number|undefined,startDate:'',endDate:''})
const form=reactive({supplierId:undefined as number|undefined,number:undefined as number|undefined,receiveDate:'',temperature:'',transport:''})
async function load(){loading.value=true;try{const d=await getReceivingOrders(query);rows.value=d.list||[];total.value=d.total||0}catch(e:any){ElMessage.error(e.message||'加载失败')}finally{loading.value=false}}
async function loadSuppliers(){try{const d=await getSuppliers({pageNum:0,pageSize:20});suppliers.value=d.list||[]}catch(e:any){ElMessage.error(e.message||'供应商加载失败')}}
function reset(){Object.assign(query,{pageNum:0,supplierId:undefined,startDate:'',endDate:''});load()}
async function exportOrder(row:ReceivingOrder){try{const {blob,filename}=await exportReceivingItems(row.id);const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=filename||`收货单_${row.id}_明细.xlsx`;a.click();URL.revokeObjectURL(u);ElMessage.success('导出成功')}catch(e:any){ElMessage.error(e.message||'导出失败')}}
async function completeOrder(row:ReceivingOrder){try{await ElMessageBox.confirm(`确定完成收货单 #${row.id} 的点货吗？`,'完成点货',{type:'warning'});await completeReceivingOrder(row.id);ElMessage.success('点货已完成');load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'完成点货失败')}}
async function create(){if(!form.supplierId)return ElMessage.warning('请选择供应商');try{const order=await createReceivingOrder({...form,supplierId:form.supplierId});dialogVisible.value=false;Object.assign(form,{supplierId:undefined,number:undefined,receiveDate:'',temperature:'',transport:''});ElMessage.success('创建成功');router.push(`/receiving-orders/${order.id}`)}catch(e:any){ElMessage.error(e.message||'创建失败')}}
function pt(v:string){return v==='COMPLETED'?'success':v==='CHECKING'?'warning':v==='DRAFT'?'info':'primary'}
function pl(v:string){return ({DRAFT:'草稿',READY:'待点货',CHECKING:'点货中',COMPLETED:'已完成'} as any)[v]||v||'-'}
onMounted(()=>{load();loadSuppliers()})
</script>
<template><div><div class="page-title"><div><h2>收货单管理</h2><p>管理来货单、Excel 导入和点货</p></div><el-button type="primary" @click="dialogVisible=true">新建收货单</el-button></div><el-card shadow="never"><el-form :inline="true" :model="query"><el-form-item label="供应商"><el-select v-model="query.supplierId" clearable placeholder="全部" style="width:180px"><el-option v-for="s in suppliers" :key="s.id" :label="s.supplierName" :value="s.id"/></el-select></el-form-item><el-form-item label="收货日期"><el-date-picker v-model="query.startDate" type="date" value-format="YYYY-MM-DD" placeholder="开始"/><span style="margin:0 8px">-</span><el-date-picker v-model="query.endDate" type="date" value-format="YYYY-MM-DD" placeholder="结束"/></el-form-item><el-form-item><el-button type="primary" @click="query.pageNum=0;load()">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="number" label="Number" width="100"/><el-table-column prop="supplierName" label="供应商" min-width="160"/><el-table-column prop="receiveDate" label="收货日期" width="120"/><el-table-column prop="temperature" label="温度" width="90"/><el-table-column prop="transport" label="运输公司" min-width="140"/><el-table-column label="进度" width="100"><template #default="{row}"><el-tag :type="pt(row.progress)">{{pl(row.progress)}}</el-tag></template></el-table-column><el-table-column label="操作" width="260" fixed="right"><template #default="{row}"><el-button link type="primary" @click="router.push(`/receiving-orders/${row.id}`)">详情</el-button><el-button v-if="row.progress==='COMPLETED'" link type="success" @click="exportOrder(row)">导出</el-button><template v-else><el-button link type="success" @click="router.push(`/receiving-orders/${row.id}/check`)">点货</el-button><el-button link type="warning" @click="completeOrder(row)">完成</el-button></template></template></el-table-column></el-table><div class="pagination"><el-pagination :current-page="query.pageNum+1" :page-size="query.pageSize" :total="total" layout="total,sizes,prev,pager,next,jumper" :page-sizes="[10,20,50]" @current-change="(p:number)=>{query.pageNum=p-1;load()}" @size-change="(s:number)=>{query.pageSize=s;query.pageNum=0;load()}"/></div></el-card><el-dialog v-model="dialogVisible" title="新建收货单" width="520px"><el-form label-width="90px"><el-form-item label="供应商" required><el-select v-model="form.supplierId" filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.supplierName" :value="s.id"/></el-select></el-form-item><el-form-item label="Number"><el-input-number v-model="form.number" :min="0" :precision="0"/></el-form-item><el-form-item label="收货日期"><el-date-picker v-model="form.receiveDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="温度"><el-input v-model="form.temperature" placeholder="例如 -18"/></el-form-item><el-form-item label="运输公司"><el-input v-model="form.transport"/></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></template></el-dialog></div></template>